// ❌ OLD: Animating `left` changes geometry, so every animation frame
// runs the full main-thread pipeline: style recalc, layout (the
// element's position moves, potentially reflowing others), paint
// recording, and re-raster — all on the main thread, competing with
// your JS. If the main thread is busy, the animation stutters.
const el = document.querySelector('.box');

el.animate([{ left: '0px' }, { left: '200px' }], {
  duration: 1000,
}); // ❌ OLD: layout-triggering animation

// Also: the element likely isn't on its own composited layer, so every
// frame re-rasterizes the affected region.

// ✅ NEW: Animating transform (translateX) is compositor-driven: the
// element is promoted to a layer and the compositor thread updates its
// transform per frame. No layout, no paint, no main-thread work — the
// animation stays smooth even when the main thread is busy.
const el = document.querySelector('.box');

el.animate([{ transform: 'translateX(0)' }, { transform: 'translateX(200px)' }], {
  duration: 1000,
}); // ✅ NEW: compositor-only animation

// To guarantee layer promotion up front, use will-change: transform
// (or leave the animation to trigger auto-promotion). The GPU just
// repositions an existing texture every frame.
